// AI Packet Drafter
// ---------------------------------------------------------------------------
// Fully front-end: award context comes from awards.json + a scrape of the
// award page, the user's documents are parsed in the browser, the draft is
// generated by the user's chosen provider (UF NaviGator, OpenAI, or Anthropic
// Claude) called directly from the browser with their own API key, and the
// .docx is built and downloaded locally.
//
// Privacy: nothing is persisted. Uploaded files, extracted text and the draft
// live only in this modal's memory and are discarded when it closes. The API
// key is held in a module variable for the lifetime of the tab (never written
// to localStorage/sessionStorage/cookies) so users don't retype it per award.
// ---------------------------------------------------------------------------

const LIBS = {
  pdfjs: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
  pdfWorker: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
  mammoth: 'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js',
  docx: 'https://unpkg.com/docx@8.5.0/build/index.umd.js'
};

const MAX_CHARS_PER_FILE = 25000;
const MAX_CHARS_ALL_FILES = 60000;
const MAX_CHARS_AWARD_PAGE = 15000;

const PACKET_SECTIONS = [
  { id: 'cover', label: 'Cover / nomination letter', checked: true },
  { id: 'statement', label: 'Personal statement / narrative', checked: true },
  { id: 'evidence', label: 'Criteria-aligned evidence summary', checked: true },
  { id: 'support', label: 'Letter of support template (for recommenders)', checked: false },
  { id: 'checklist', label: 'Submission checklist', checked: true }
];

// Official Anthropic TypeScript SDK, ESM build (no bundler on this site)
const ANTHROPIC_SDK_URL = 'https://cdn.jsdelivr.net/npm/@anthropic-ai/sdk@1.3.0/+esm';

// Default-model preferences are tried in order; within one, the newest version
// the account offers wins (see refreshModels), so new generations become the
// default automatically. OpenAI's tiered models: Terra (balanced speed/cost,
// preferred for drafting), then Sol (most capable), e.g. gpt-5.6-terra,
// gpt-6.1-terra. LATEST_GPT is the fallback for plain flagship ids
// (gpt-5.2, gpt-6), excluding mini/nano/chat/pro variants.
const GPT_TERRA = /^gpt-\d+(\.\d+)?-terra$/i;
const GPT_SOL = /^gpt-\d+(\.\d+)?-sol$/i;
const LATEST_GPT = /^gpt-([5-9]|\d{2,})(\.\d+)?$/i;

// AI providers. All three accept direct browser (CORS) requests.
const PROVIDERS = {
  navigator: {
    label: 'UF NaviGator',
    kind: 'openai',
    baseUrl: 'https://api.ai.it.ufl.edu/v1',
    keyHint: 'sk-… (UF NaviGator key)',
    prefer: [GPT_TERRA, GPT_SOL, LATEST_GPT, /^gpt-4\.1$/i, /^gpt-4o$/i, /claude.*sonnet/i]
  },
  openai: {
    label: 'OpenAI (ChatGPT)',
    kind: 'openai',
    baseUrl: 'https://api.openai.com/v1',
    keyHint: 'sk-… (API key from platform.openai.com)',
    help: 'Needs an OpenAI API key with billing enabled. A ChatGPT Plus subscription alone does not include API access.',
    prefer: [GPT_TERRA, GPT_SOL, LATEST_GPT, /^gpt-4\.1$/i, /^gpt-4o$/i],
    filter: id => /^(gpt|o\d|chatgpt)/i.test(id) && !/realtime|audio|transcribe|tts|image|search|instruct/i.test(id)
  },
  anthropic: {
    label: 'Anthropic (Claude)',
    kind: 'anthropic',
    keyHint: 'sk-ant-… (API key from console.anthropic.com)',
    help: 'Needs an Anthropic API key. A Claude.ai Pro subscription alone does not include API access.',
    prefer: [/^claude-opus-5-5$/, /^claude-opus-\d/, /^claude-sonnet-\d/]
  }
};

// Claude models that accept the server-side refusal fallback ("default" routing)
const CLAUDE_FALLBACK_MODELS = /^claude-(fable-5-[12]|opus-5-5|opus-5|sonnet-5-5)$/;

// Tab-lifetime memory only (cleared on reload). Not persisted anywhere.
// Keys/models are tracked per provider so switching back and forth is painless.
const session = {
  provider: 'navigator',
  keys: {},       // provider -> API key
  models: {},     // provider -> [model ids]
  model: {},      // provider -> selected model id
  maxTokens: {},  // model id -> output token cap (Anthropic Models API)
  baseUrl: { navigator: PROVIDERS.navigator.baseUrl, openai: PROVIDERS.openai.baseUrl }
};

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

const scriptCache = new Map();
function loadScript(src) {
  if (!scriptCache.has(src)) {
    scriptCache.set(src, new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.async = true;
      s.onload = resolve;
      s.onerror = () => {
        scriptCache.delete(src);
        reject(new Error(`Failed to load library: ${src}`));
      };
      document.head.appendChild(s);
    }));
  }
  return scriptCache.get(src);
}

function esc(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function truncate(text, max) {
  if (text.length <= max) return { text, truncated: false };
  return { text: text.slice(0, max) + '\n[...truncated...]', truncated: true };
}

function normalizeWhitespace(text) {
  return text
    .replace(/\r/g, '')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  return isNaN(d) ? iso : d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
}

function slug(text) {
  return String(text).replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 60);
}

// ---------------------------------------------------------------------------
// Award page scraping (CORS-safe fallbacks)
// ---------------------------------------------------------------------------

function htmlToText(html) {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  doc.querySelectorAll('script, style, noscript, svg, nav, header, footer, form, iframe, [role="navigation"], [aria-hidden="true"]')
    .forEach(el => el.remove());
  const main = doc.querySelector('main, [role="main"], article, #content, .content') || doc.body;
  if (!main) return '';
  // Preserve some block structure
  main.querySelectorAll('br').forEach(br => br.replaceWith('\n'));
  main.querySelectorAll('p, div, li, h1, h2, h3, h4, h5, h6, tr, section').forEach(el => el.append('\n'));
  main.querySelectorAll('li').forEach(li => li.prepend('- '));
  return normalizeWhitespace(main.textContent || '');
}

function cleanReaderMarkdown(md) {
  // r.jina.ai returns markdown with metadata header + lots of nav links/images.
  const body = md.includes('Markdown Content:') ? md.split('Markdown Content:').slice(1).join('Markdown Content:') : md;
  return normalizeWhitespace(
    body
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')                 // images
      .replace(/\[([^\]]*)\]\((?:javascript:|#)[^)]*\)/g, '') // js/anchor links
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')              // keep link text
      .split('\n')
      .filter(line => line.trim().length > 2)
      .join('\n')
  );
}

async function fetchWithTimeout(url, ms = 15000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  try {
    return await fetch(url, { signal: ctrl.signal });
  } finally {
    clearTimeout(t);
  }
}

async function scrapeAwardPage(url) {
  if (!url || !/^https?:\/\//i.test(url)) throw new Error('No valid award page URL');

  const attempts = [
    // 1. Direct (works only if the page allows CORS)
    async () => {
      const r = await fetchWithTimeout(url, 8000);
      if (!r.ok) throw new Error(r.status);
      return htmlToText(await r.text());
    },
    // 2. Jina reader – returns clean-ish markdown, CORS enabled
    async () => {
      const r = await fetchWithTimeout(`https://r.jina.ai/${url}`, 20000);
      if (!r.ok) throw new Error(r.status);
      return cleanReaderMarkdown(await r.text());
    },
    // 3. AllOrigins raw proxy – returns HTML
    async () => {
      const r = await fetchWithTimeout(`https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`, 20000);
      if (!r.ok) throw new Error(r.status);
      return htmlToText(await r.text());
    }
  ];

  for (const attempt of attempts) {
    try {
      const text = await attempt();
      if (text && text.length > 200) return truncate(text, MAX_CHARS_AWARD_PAGE).text;
    } catch {
      // try next strategy
    }
  }
  throw new Error('Could not read the award page');
}

// ---------------------------------------------------------------------------
// Document text extraction (in-browser)
// ---------------------------------------------------------------------------

async function extractPdf(file) {
  await loadScript(LIBS.pdfjs);
  const pdfjsLib = window.pdfjsLib;
  pdfjsLib.GlobalWorkerOptions.workerSrc = LIBS.pdfWorker;
  const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
  const pages = [];
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    pages.push(content.items.map(it => it.str + (it.hasEOL ? '\n' : ' ')).join(''));
  }
  await pdf.destroy();
  return pages.join('\n\n');
}

async function extractDocx(file) {
  await loadScript(LIBS.mammoth);
  const result = await window.mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
  return result.value;
}

async function extractText(file) {
  const name = file.name.toLowerCase();
  if (name.endsWith('.pdf') || file.type === 'application/pdf') return extractPdf(file);
  if (name.endsWith('.docx')) return extractDocx(file);
  if (/\.(txt|md|markdown|rtf|csv)$/.test(name) || file.type.startsWith('text/')) return file.text();
  if (name.endsWith('.doc')) throw new Error('Legacy .doc is not supported — save it as .docx or PDF');
  throw new Error('Unsupported file type (use PDF, DOCX, TXT or MD)');
}

// ---------------------------------------------------------------------------
// LLM providers
//  - OpenAI-compatible chat completions (UF NaviGator, OpenAI) via fetch + SSE
//  - Anthropic Messages API via the official SDK (browser mode)
// ---------------------------------------------------------------------------

let anthropicSdkPromise = null;
function loadAnthropicSdk() {
  anthropicSdkPromise ||= import(ANTHROPIC_SDK_URL)
    .then(m => m.default || m.Anthropic)
    .catch(err => { anthropicSdkPromise = null; throw err; });
  return anthropicSdkPromise;
}

async function anthropicClient(apiKey) {
  const Anthropic = await loadAnthropicSdk();
  // The key belongs to the person using the page and only goes to
  // api.anthropic.com from their own browser, so browser access is intended.
  return new Anthropic({ apiKey, dangerouslyAllowBrowser: true, maxRetries: 2 });
}

function friendlyError(err, providerLabel) {
  const status = err?.status;
  if (status === 401 || status === 403) return `${providerLabel} rejected the API key (${status}). Check that it is correct and active.`;
  if (status === 404) return `Model not found or not available to this key (${status}). Pick another model.`;
  if (status === 429) return `${providerLabel} rate limit or quota reached (429). Wait a moment, or check your plan's credits.`;
  if (/Failed to fetch|NetworkError|Connection error/i.test(err?.message || '')) {
    return `Could not reach ${providerLabel}. Check the endpoint and your network/VPN.`;
  }
  return err?.message || String(err);
}

async function listModels(cfg) {
  const provider = PROVIDERS[cfg.provider];

  if (provider.kind === 'anthropic') {
    const client = await anthropicClient(cfg.apiKey);
    const ids = [];
    for await (const m of client.models.list({ limit: 100 })) {
      ids.push(m.id);
      if (m.max_tokens) session.maxTokens[m.id] = m.max_tokens;
    }
    return ids; // API returns newest first; keep that order
  }

  const r = await fetch(cfg.baseUrl.replace(/\/+$/, '') + '/models', {
    headers: { Authorization: `Bearer ${cfg.apiKey}` }
  });
  if (!r.ok) throw Object.assign(new Error(`Model list failed (${r.status})`), { status: r.status });
  const data = await r.json();
  const keep = provider.filter || (id => !/embed|whisper|tts|dall-?e|image|rerank|moderation|transcri|speech/i.test(id));
  return (data.data || []).map(m => m.id).filter(id => id && keep(id)).sort();
}

// Streams the draft; calls onDelta(text) for each chunk. Returns the full text.
async function streamChat(cfg, prompt, onDelta, signal) {
  return PROVIDERS[cfg.provider].kind === 'anthropic'
    ? streamAnthropic(cfg, prompt, onDelta, signal)
    : streamOpenAICompatible(cfg, prompt, onDelta, signal);
}

async function streamAnthropic(cfg, { system, user }, onDelta, signal) {
  const client = await anthropicClient(cfg.apiKey);
  const params = {
    model: cfg.model,
    max_tokens: Math.min(64000, session.maxTokens[cfg.model] || 64000),
    system,
    messages: [{ role: 'user', content: user }]
  };

  // On models that support it, the API retries a declined request on a fallback model
  const stream = CLAUDE_FALLBACK_MODELS.test(cfg.model)
    ? client.beta.messages.stream(
        { ...params, betas: ['server-side-fallback-2026-07-01'], fallbacks: 'default' },
        { signal })
    : client.messages.stream(params, { signal });

  let full = '';
  for await (const event of stream) {
    if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
      full += event.delta.text;
      onDelta(event.delta.text);
    }
  }

  const final = await stream.finalMessage();
  if (final.stop_reason === 'refusal') {
    throw Object.assign(
      new Error('Claude declined to complete this request. Try rephrasing your extra instructions or choose another model.'),
      { discardPartial: true });
  }
  if (final.stop_reason === 'max_tokens') {
    const note = '\n\n[ADD: the draft hit the length limit here. Regenerate with fewer sections or finish this part manually]';
    full += note;
    onDelta(note);
  }
  return full;
}

// GPT-5 and later (except -chat variants) and o-series models reason silently
// before writing; asking for low effort keeps drafting fast.
function isOpenAIReasoningModel(model) {
  return /^(gpt-([5-9]|\d{2,})(?!.*-chat)|o\d)/i.test(model);
}

async function streamOpenAICompatible(cfg, { system, user }, onDelta, signal) {
  const send = withEffort => fetch(cfg.baseUrl.replace(/\/+$/, '') + '/chat/completions', {
    method: 'POST',
    signal,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${cfg.apiKey}`
    },
    // No temperature: reasoning models reject non-default values
    body: JSON.stringify({
      model: cfg.model,
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
      stream: true,
      ...(withEffort ? { reasoning_effort: 'low' } : {})
    })
  });

  const wantEffort = isOpenAIReasoningModel(cfg.model);
  let r = await send(wantEffort);
  // If this model or gateway doesn't accept reasoning_effort, retry once without it
  if (wantEffort && r.status === 400) {
    const text = await r.clone().text().catch(() => '');
    if (/reasoning/i.test(text)) r = await send(false);
  }

  if (!r.ok) {
    let detail = '';
    try {
      const j = await r.json();
      detail = j.error?.message || j.detail || JSON.stringify(j);
    } catch {
      detail = await r.text().catch(() => '');
    }
    throw Object.assign(new Error(`API error ${r.status}${detail ? `: ${String(detail).slice(0, 300)}` : ''}`), { status: r.status });
  }

  const contentType = r.headers.get('content-type') || '';
  if (!contentType.includes('text/event-stream')) {
    // Server ignored stream:true; handle a normal JSON response
    const j = await r.json();
    const text = j.choices?.[0]?.message?.content || '';
    onDelta(text);
    return text;
  }

  const reader = r.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let full = '';
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split('\n');
    buffer = lines.pop();
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed.startsWith('data:')) continue;
      const payload = trimmed.slice(5).trim();
      if (payload === '[DONE]') return full;
      try {
        const delta = JSON.parse(payload).choices?.[0]?.delta?.content;
        if (delta) {
          full += delta;
          onDelta(delta);
        }
      } catch {
        // ignore keep-alives / partial lines
      }
    }
  }
  return full;
}

function buildMessages({ award, awardPageText, files, role, nomineeName, sections, instructions }) {
  const sectionLabels = PACKET_SECTIONS.filter(s => sections.includes(s.id)).map(s => s.label);

  const system = `You are an expert academic award-application writer at the University of Florida. You draft strong, specific, honest award packets.

Who reads what you write: the award committee. The applicant will edit your draft in Word and submit it, so every sentence that is not highlighted must read as finished, persuasive application text in the writer's own voice. The applicant reviews every yellow-highlighted item before submitting; highlighting is how you tell them what needs their attention.

Content rules:
- Ground every claim in the applicant's documents. Never invent achievements, numbers, titles, dates, publications, outcomes or quotes.
- Map the applicant's evidence to the award's stated criteria and requirements, and follow any length limits or required components on the award page.
- Use a professional, confident, warm academic tone. Present documented work positively and concretely; do not hedge or apologize for it.
- Never write commentary about the source material, the evidence, or the drafting process in the packet text. For example, do not write sentences like "The supplied CV does not report...", "These documents do not establish...", "The award page does not specify...", or "This draft maps...". If evidence is missing, leave the claim out of the prose and use an [ADD: ...] placeholder instead.

Highlighting rules (each marker below is rendered in yellow for the applicant to resolve):
- [ADD: what to add] - information the packet needs but the documents do not contain, e.g. [ADD: one online-course engagement metric with timeframe]. Put it where the information belongs. Keep it short and specific.
- ==claim text== - wrap any statement the applicant must verify: facts that come from the user's additional instructions rather than the uploaded documents, numbers or dates you inferred, paraphrased characterizations of impact, and anything you are not certain the documents support. The wrapped text stays part of the sentence, e.g. "I redesigned ==three online courses serving 1,300 students per semester== to...".
- [NOTE: concern] - a concern the applicant must resolve before submitting, such as an eligibility mismatch with the award rules. State each concern once, briefly, at the very top of the packet directly under the title, never inside the body text. Then write the packet as strongly as the documented evidence allows.
- Use no other square brackets or == markers anywhere.

Output format (strict): Markdown only, no code fences, no preamble or closing commentary.
- Start with a single "# " title line for the packet.
- Use "## " for each packet component and "### " for sub-headings.
- Use paragraphs, "- " bullet lists, and **bold** sparingly.
- Tables are allowed as standard Markdown pipe tables (header row, then |---| separator, one row per line). Inside a cell use "<br>" for line breaks; no HTML anywhere else.
- Use plain ASCII hyphens (-) and regular spaces; no special Unicode hyphens or HTML entities.
- Put a line containing only "---" between packet components (it becomes a page break).`;

  const fileBlock = files.length
    ? files.map(f => `=== DOCUMENT: ${f.name} ===\n${f.text}`).join('\n\n')
    : '(No documents were provided. Use placeholders for all applicant-specific details.)';

  const user = `Draft an award application packet.

## Award (from our database)
Title: ${award.title}
Level: ${award.level || 'n/a'}
Eligible: ${award.awardFor || 'n/a'}
Recognition type: ${award.type || 'n/a'}
Application mode: ${award.applicationMode || 'n/a'}
Final deadline: ${formatDate(award.deadlineDate) || 'n/a'}
Internal deadline: ${award.internalDeadline || 'n/a'}
Requirements: ${award.requirements || 'n/a'}
Award page: ${award.link || 'n/a'}

## Award page content (scraped; may contain navigation noise)
${awardPageText || '(Not available — rely on the requirements above.)'}

## Who is writing
${role === 'nominator'
    ? `A nominator is nominating ${nomineeName || 'a colleague'} for this award. Write nomination materials in the nominator's voice; the uploaded documents describe the nominee.`
    : `The applicant ${nomineeName ? `(${nomineeName}) ` : ''}is applying for themselves. Write in the applicant's first-person voice where appropriate.`}

## Packet components to include (in this order)
${sectionLabels.map((l, i) => `${i + 1}. ${l}`).join('\n')}

${instructions ? `## Additional instructions from the user\n(Any facts stated here are not backed by the uploaded documents: wrap them in ==...== wherever you use them so the applicant verifies them.)\n${instructions}\n\n` : ''}## Applicant documents
${fileBlock}`;

  return { system, user };
}

// ---------------------------------------------------------------------------
// Minimal, safe Markdown -> HTML (input is escaped first)
// ---------------------------------------------------------------------------

// Normalize characters models like to emit that render as odd glyphs in
// browsers/Word (non-breaking hyphens, narrow NBSPs, zero-width chars, entities).
function cleanModelText(text) {
  return text
    .replace(/[‐‑‒⁃]/g, '-')
    .replace(/[     ]/g, ' ')
    .replace(/[​-‍⁠﻿­]/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/&ndash;/gi, '–')
    .replace(/&mdash;/gi, '—');
}

function inlineMd(text) {
  let s = esc(text);
  s = s.replace(/&lt;br\s*\/?&gt;/gi, '<br>');
  // Review markers: [ADD: ...] / [NOTE: ...] placeholders and ==claims to verify==
  s = s.replace(/\[([^\]\n]{2,300})\]/g, '<mark>[$1]</mark>');
  s = s.replace(/==([^=\n]{1,500})==/g, '<mark>$1</mark>');
  s = s.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/__([^_\n]+)__/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^*\w])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  s = s.replace(/(^|[^_\w])_([^_\n]+)_(?!_)/g, '$1<em>$2</em>');
  return s;
}

function markdownToHtml(md) {
  const lines = cleanModelText(md).replace(/^```[a-z]*\n?|```$/gim, '').split('\n');
  const out = [];
  let para = [];
  let list = null; // { type: 'ul'|'ol', items: [] }
  let table = null; // raw "| a | b |" lines

  const flushPara = () => {
    if (para.length) out.push(`<p>${inlineMd(para.join(' '))}</p>`);
    para = [];
  };
  const flushList = () => {
    if (list) out.push(`<${list.type}>${list.items.map(i => `<li>${inlineMd(i)}</li>`).join('')}</${list.type}>`);
    list = null;
  };
  const flushTable = () => {
    if (!table) return;
    const isSep = row => row.length > 0 && row.every(c => /^:?-{2,}:?$/.test(c));
    let rows = table.map(r => r.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim()));
    let head = null;
    if (rows.length > 1 && isSep(rows[1])) { head = rows[0]; rows = rows.slice(2); }
    rows = rows.filter(r => !isSep(r));
    const cols = Math.max(head ? head.length : 0, ...rows.map(r => r.length));
    const pad = r => [...r, ...Array(Math.max(0, cols - r.length)).fill('')];
    out.push(`<table>${head ? `<thead><tr>${pad(head).map(c => `<th>${inlineMd(c)}</th>`).join('')}</tr></thead>` : ''}<tbody>${
      rows.map(r => `<tr>${pad(r).map(c => `<td>${inlineMd(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`);
    table = null;
  };

  for (const raw of lines) {
    const line = raw.trimEnd();
    let m;
    if (/^\s*\|.*\|\s*$/.test(line)) { flushPara(); flushList(); (table ||= []).push(line); continue; }
    flushTable();
    if (!line.trim()) { flushPara(); flushList(); continue; }
    if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) { flushPara(); flushList(); out.push('<hr>'); continue; }
    if ((m = line.match(/^(#{1,6})\s+(.*)$/))) {
      flushPara(); flushList();
      const level = Math.min(m[1].length, 3);
      out.push(`<h${level}>${inlineMd(m[2].replace(/#+\s*$/, ''))}</h${level}>`);
      continue;
    }
    if ((m = line.match(/^\s*[-*•]\s+(.*)$/))) {
      flushPara();
      if (!list || list.type !== 'ul') { flushList(); list = { type: 'ul', items: [] }; }
      list.items.push(m[1]);
      continue;
    }
    if ((m = line.match(/^\s*\d+[.)]\s+(.*)$/))) {
      flushPara();
      if (!list || list.type !== 'ol') { flushList(); list = { type: 'ol', items: [] }; }
      list.items.push(m[1]);
      continue;
    }
    flushList();
    para.push(line.trim());
  }
  flushTable();
  flushPara();
  flushList();
  return out.join('\n');
}

// ---------------------------------------------------------------------------
// Edited preview DOM -> .docx
// ---------------------------------------------------------------------------

function runsFromNode(node, docx, fmt = {}) {
  const runs = [];
  node.childNodes.forEach(child => {
    if (child.nodeType === Node.TEXT_NODE) {
      const text = child.textContent.replace(/\s+/g, ' ');
      if (text) runs.push(new docx.TextRun({ text, ...fmt }));
      return;
    }
    if (child.nodeType !== Node.ELEMENT_NODE) return;
    const tag = child.tagName.toLowerCase();
    if (tag === 'br') { runs.push(new docx.TextRun({ text: '', break: 1 })); return; }
    const next = { ...fmt };
    if (tag === 'strong' || tag === 'b') next.bold = true;
    if (tag === 'em' || tag === 'i') next.italics = true;
    if (tag === 'u') next.underline = {};
    if (tag === 'mark') next.highlight = 'yellow';
    runs.push(...runsFromNode(child, docx, next));
  });
  return runs;
}

let listInstance = 0;

function blocksFromElement(root, docx) {
  const blocks = [];
  const HEADINGS = { h1: docx.HeadingLevel.HEADING_1, h2: docx.HeadingLevel.HEADING_2, h3: docx.HeadingLevel.HEADING_3 };
  const BLOCK_TAGS = new Set(['p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'ul', 'ol', 'li', 'hr', 'blockquote', 'section', 'table']);

  const pushParagraph = (el, opts = {}) => {
    const children = runsFromNode(el, docx);
    if (!children.length && !opts.keepEmpty) return;
    blocks.push(new docx.Paragraph({ children, spacing: { after: 160 }, ...opts }));
  };

  root.childNodes.forEach(node => {
    if (node.nodeType === Node.TEXT_NODE) {
      if (node.textContent.trim()) blocks.push(new docx.Paragraph({ children: [new docx.TextRun(node.textContent.trim())] }));
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const tag = node.tagName.toLowerCase();

    if (HEADINGS[tag] || /^h[4-6]$/.test(tag)) {
      blocks.push(new docx.Paragraph({
        heading: HEADINGS[tag] || docx.HeadingLevel.HEADING_3,
        children: runsFromNode(node, docx),
        spacing: { before: 240, after: 120 }
      }));
    } else if (tag === 'table') {
      const trs = [...node.querySelectorAll('tr')];
      const cols = Math.max(1, ...trs.map(tr => tr.children.length));
      const colWidth = Math.floor(9360 / cols); // 6.5" text width in twips
      if (trs.length) {
        blocks.push(new docx.Table({
          width: { size: 100, type: docx.WidthType.PERCENTAGE },
          columnWidths: Array(cols).fill(colWidth),
          rows: trs.map(tr => new docx.TableRow({
            ...(tr.parentElement?.tagName === 'THEAD' ? { tableHeader: true } : {}),
            children: [...tr.children].map(cell => {
              const isHead = cell.tagName === 'TH';
              return new docx.TableCell({
                width: { size: colWidth, type: docx.WidthType.DXA },
                margins: { top: 80, bottom: 80, left: 120, right: 120 },
                shading: isHead ? { fill: 'E8ECF8', type: docx.ShadingType.CLEAR, color: 'auto' } : undefined,
                children: [new docx.Paragraph({ children: runsFromNode(cell, docx, isHead ? { bold: true } : {}) })]
              });
            })
          }))
        }));
        blocks.push(new docx.Paragraph({ children: [], spacing: { after: 160 } }));
      }
    } else if (tag === 'hr') {
      blocks.push(new docx.Paragraph({ children: [new docx.PageBreak()] }));
    } else if (tag === 'ul' || tag === 'ol') {
      const instance = ++listInstance; // each <ol> restarts at 1
      Array.from(node.children).forEach(li => {
        blocks.push(new docx.Paragraph({
          children: runsFromNode(li, docx),
          ...(tag === 'ul'
            ? { bullet: { level: 0 } }
            : { numbering: { reference: 'packet-numbers', level: 0, instance } }),
          spacing: { after: 80 }
        }));
      });
    } else if ([...node.children].some(c => BLOCK_TAGS.has(c.tagName.toLowerCase()))) {
      // Wrapper produced by contenteditable editing – recurse
      blocks.push(...blocksFromElement(node, docx));
    } else {
      pushParagraph(node);
    }
  });
  return blocks;
}

// Yellow-highlighted items (placeholders, notes, claims to verify) still in the draft
function countReviewItems(el) {
  return [...el.querySelectorAll('mark')].filter(m => m.textContent.trim()).length;
}

async function buildDocx(previewEl, award) {
  await loadScript(LIBS.docx);
  const docx = window.docx;

  // Highlighted notice at the top of the .docx while review items remain
  function reviewBanner(el, docx) {
    const count = countReviewItems(el);
    if (!count) return [];
    const border = { style: docx.BorderStyle.SINGLE, size: 8, color: 'D97706', space: 6 };
    return [new docx.Paragraph({
      border: { top: border, bottom: border, left: border, right: border },
      shading: { type: docx.ShadingType.CLEAR, color: 'auto', fill: 'FEF3C7' },
      spacing: { after: 240 },
      children: [
        new docx.TextRun({ text: `BEFORE SUBMITTING: ${count} yellow-highlighted item${count === 1 ? '' : 's'} need${count === 1 ? 's' : ''} your review. `, bold: true }),
        new docx.TextRun({ text: 'Verify each highlighted claim against your records, fill in every [ADD] placeholder, and resolve every [NOTE]. Remove each highlight once checked, then delete this box.' })
      ]
    })];
  }

  const doc = new docx.Document({
    creator: 'EEd Recognitions Navigator',
    title: `${award.title} – Application Packet (Draft)`,
    styles: {
      default: { document: { run: { font: 'Calibri', size: 22 } } },
      paragraphStyles: [
        { id: 'Heading1', name: 'Heading 1', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { size: 36, bold: true, color: '0021A5' } },
        { id: 'Heading2', name: 'Heading 2', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { size: 28, bold: true, color: '0021A5' } },
        { id: 'Heading3', name: 'Heading 3', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { size: 24, bold: true, color: '333333' } }
      ]
    },
    numbering: {
      config: [{
        reference: 'packet-numbers',
        levels: [{ level: 0, format: docx.LevelFormat.DECIMAL, text: '%1.', alignment: docx.AlignmentType.START,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      }]
    },
    sections: [{
      properties: { page: { margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 } } },
      footers: {
        default: new docx.Footer({
          children: [new docx.Paragraph({
            alignment: docx.AlignmentType.CENTER,
            children: [new docx.TextRun({
              text: 'AI-assisted draft — verify every detail and replace highlighted placeholders before submitting.',
              italics: true, size: 16, color: '777777'
            })]
          })]
        })
      },
      children: [...reviewBanner(previewEl, docx), ...blocksFromElement(previewEl, docx)]
    }]
  });

  const blob = await docx.Packer.toBlob(doc);
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${slug(award.title) || 'award'}-packet-draft.docx`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}

